import{_ as d,o as r,c as e,a3 as a}from"./chunks/framework.lx4Uzxpr.js";const u=JSON.parse('{"title":"知识库大纲","description":"全站知识地图：机器人 8 栏目的知识主线、知识点清单与写作规划，含原理/实现的分工规则","frontmatter":{"title":"知识库大纲","date":"2026-10-23T00:00:00.000Z","tags":["知识库","规划"],"category":"notes","description":"全站知识地图：机器人 8 栏目的知识主线、知识点清单与写作规划，含原理/实现的分工规则","sidebar":false},"headers":[],"relativePath":"notes/大纲.md","filePath":"notes/大纲.md"}'),o={name:"notes/大纲.md"};function h(l,t,i,n,s,b){return r(),e("div",null,t[0]||(t[0]=[a('<h1 id="知识库大纲" tabindex="-1">知识库大纲 <a class="header-anchor" href="#知识库大纲" aria-label="Permalink to “知识库大纲”">​</a></h1><blockquote><p>这是一份持续维护的活文档：它定义&quot;写什么、按什么逻辑写、写到什么程度&quot;。新文章动笔前先到这里认领位置，写完回来更新状态。</p><p><strong>进度</strong>：首批条目已于 2026-10-24 全部入库（下表标&quot;已写&quot;并附文件名）。</p></blockquote><h2 id="使用规则" tabindex="-1">使用规则 <a class="header-anchor" href="#使用规则" aria-label="Permalink to “使用规则”">​</a></h2><p><strong>标注图例</strong>：</p><table tabindex="0"><thead><tr><th>标注</th><th>含义</th></tr></thead><tbody><tr><td>已写</td><td>文章已入库（附文件名）</td></tr><tr><td>首批</td><td>与当前工作（舵机测试 / DMP / 动作库）直接相关，优先写</td></tr><tr><td>核心</td><td>该栏目的必要知识点，构成完整知识线</td></tr><tr><td>扩展</td><td>进阶或选读，有需要再写</td></tr></tbody></table><p><strong>写作结构约定</strong>（所有文章遵循同一知识观）：</p><ol><li><strong>内核 → 规则与行为 → 抽象</strong> 三段式：先理解&quot;为什么这么做&quot;（内核），由内核推导出可操作的规则与行为，最后给出更高层的抽象规则去便利之前繁琐的行为。定义力求简洁明了，晦涩处展开描述，句间保持逻辑衔接。</li><li><strong>原理类数学推理 → 数学基础；具体实现 → 对应栏目。</strong> 例如：卡尔曼滤波的理论推导在数学基础，EKF 融合实战在感知与估计。两边互相引用而不重复。</li><li><strong>单一归属 + 术语跳转。</strong> 每篇文章只属于一个栏目，跨栏目引用一律用 <code>[[术语]]</code> 跳转链接（术语表维护于 <code>.vitepress/glossary.ts</code>），不复制内容。</li></ol><p><strong>知识主线</strong>（八个栏目怎么串起来）：数学是工具 → 结构硬件是本体 → 感知让机器看世界 → 规划决策决定做什么 → 控制决定怎么动 → 软件中间件负责通信 → 系统仿真把一切拼起来验证。</p><hr><h2 id="_1-数学基础" tabindex="-1">1 数学基础 <a class="header-anchor" href="#_1-数学基础" aria-label="Permalink to “1 数学基础”">​</a></h2><blockquote><p>主线：变换的语言 → 弯曲空间上的微积分 → 带噪声的推断 → 求解方法。本栏目是全站的&quot;理论仓库&quot;，其他栏目遇到数学推理一律跳转到这里。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>线性代数的几何本质</td><td>矩阵=变换；特征值/SVD 的几何意义</td><td>核心</td></tr><tr><td>坐标变换与齐次矩阵</td><td>T 矩阵、左乘/右乘（世界系 vs 机体系）直觉</td><td>已写（transform-homogeneous）</td></tr><tr><td>旋转表示全家</td><td>欧拉角/轴角/矩阵/四元数的统一视角与选型规则</td><td>已写（rotation-representations）</td></tr><tr><td>四元数</td><td>S³ 双重覆盖、半角公式、SLERP、微分方程</td><td>已写（quaternion）</td></tr><tr><td>李群李代数 SO(3)/SE(3)</td><td>指数/对数映射、扰动模型、BCH、流形优化模式</td><td>已写（lie-groups）</td></tr><tr><td>卡尔曼滤波理论</td><td>Bayes 递推 → KF 五公式 → EKF/UKF（推导层）</td><td>已写（kalman-filter）</td></tr><tr><td>概率与高斯推断</td><td>贝叶斯、协方差、流形上的高斯</td><td>核心</td></tr><tr><td>数值优化</td><td>最小二乘、Gauss-Newton/LM、稀疏结构</td><td>核心</td></tr><tr><td>样条与插值理论</td><td>B 样条、多项式插值的数学性质</td><td>扩展</td></tr><tr><td>粒子滤波与因子图</td><td>非线性/非高斯推断</td><td>扩展</td></tr><tr><td>微分几何初步</td><td>流形、切空间、测地线</td><td>扩展</td></tr></tbody></table><h2 id="_2-结构与机构" tabindex="-1">2 结构与机构 <a class="header-anchor" href="#_2-结构与机构" aria-label="Permalink to “2 结构与机构”">​</a></h2><blockquote><p>主线：构型 → 传动 → 末端 → 设计流程。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>自由度与构型学</td><td>Grübler 公式、串联/并联、经典构型取舍</td><td>核心</td></tr><tr><td>运动副与螺旋理论</td><td>低副/高副、螺旋理论入门</td><td>扩展</td></tr><tr><td>减速器</td><td>谐波/RV/行星；背隙、刚度、反射惯量平方定律</td><td>已写（reducers）</td></tr><tr><td>末端执行器</td><td>夹爪/灵巧手/吸盘、欠驱动机构</td><td>核心</td></tr><tr><td>关节模组与准直驱</td><td>一体化关节、力矩密度</td><td>核心</td></tr><tr><td>结构设计流程</td><td>材料、轻量化、公差与装配</td><td>扩展</td></tr><tr><td>软体/仿生机构</td><td>软体驱动器、仿生构型</td><td>扩展</td></tr></tbody></table><h2 id="_3-硬件与电子" tabindex="-1">3 硬件与电子 <a class="header-anchor" href="#_3-硬件与电子" aria-label="Permalink to “3 硬件与电子”">​</a></h2><blockquote><p>主线：能量（电机）→ 驱动 → 感知器件 → 计算互联 → 供电。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>电机原理</td><td>有刷/无刷/步进/舵机：换相机制一个内核</td><td>已写（motor-principles）</td></tr><tr><td>FOC 与电流环</td><td>dq 坐标系分解、SVPWM、力矩源接口</td><td>已写（foc）</td></tr><tr><td>编码器</td><td>增量/绝对、分辨率≠精度、双编码器方案</td><td>已写（encoders）</td></tr><tr><td>IMU 器件层</td><td>MEMS 陀螺/加计误差模型（零偏/温漂/噪声密度）</td><td>核心</td></tr><tr><td>其他传感器器件</td><td>力/力矩传感器、相机、LiDAR 选型</td><td>核心</td></tr><tr><td>嵌入式与 RTOS</td><td>优先级抢占、优先级反转、总线选型</td><td>已写（embedded-rtos）</td></tr><tr><td>电源系统</td><td>功率预算、电源树、BMS 入门</td><td>核心</td></tr><tr><td>实时总线进阶</td><td>EtherCAT/CANopen 对比</td><td>扩展</td></tr><tr><td>PCB 与原理图</td><td>原理图阅读、布局布线基础</td><td>扩展</td></tr></tbody></table><h2 id="_4-感知与估计" tabindex="-1">4 感知与估计 <a class="header-anchor" href="#_4-感知与估计" aria-label="Permalink to “4 感知与估计”">​</a></h2><blockquote><p>主线：标定 → 状态估计（应用层）→ 具体模态 → SLAM。滤波理论见 1（数学基础）。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>传感器标定</td><td>内参/外参、手眼标定（AX=XB）、激励充分性</td><td>已写（sensor-calibration）</td></tr><tr><td>IMU 姿态解算</td><td>互补滤波/Mahony/Madgwick（四元数的落地应用）</td><td>已写（imu-attitude）</td></tr><tr><td>卡尔曼滤波应用</td><td>ESKF 三件套、NIS 一致性检验、调参即分配信任</td><td>已写（kalman-fusion）</td></tr><tr><td>视觉感知</td><td>特征点/光流/立体视觉、视觉伺服</td><td>扩展</td></tr><tr><td>点云处理</td><td>ICP/NDT、分割与降采样</td><td>扩展</td></tr><tr><td>SLAM 框架</td><td>前端里程计、后端优化、回环检测</td><td>扩展</td></tr><tr><td>定位</td><td>AMCL、RTK-GPS</td><td>扩展</td></tr></tbody></table><h2 id="_5-规划与决策" tabindex="-1">5 规划与决策 <a class="header-anchor" href="#_5-规划与决策" aria-label="Permalink to “5 规划与决策”">​</a></h2><blockquote><p>主线：架构（做什么）→ 路径（走哪）→ 轨迹（怎么走）→ 任务（先做什么）。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>状态机</td><td>从需求到状态爆炸；HSM</td><td>已写（finite-state-machine）</td></tr><tr><td>行为树</td><td>Tick 三态、反应式/记忆式、黑板</td><td>已写（behavior-tree）</td></tr><tr><td>混合决策架构</td><td>三层分工、三个动词接口、决策资产化</td><td>已写（hybrid-decision）</td></tr><tr><td>全局规划</td><td>A* → 采样法（RRT*）→ state lattice</td><td>核心</td></tr><tr><td>局部规划与避障</td><td>DWA/TEB/速度障碍</td><td>核心</td></tr><tr><td>轨迹生成</td><td>样条轨迹、时间最优 TOPP（样条理论在数学基础）</td><td>核心</td></tr><tr><td>任务规划</td><td>TAMP 简介</td><td>扩展</td></tr><tr><td>足式步态规划</td><td>ZMP、足端轨迹</td><td>扩展</td></tr></tbody></table><h2 id="_6-控制与运动生成" tabindex="-1">6 控制与运动生成 <a class="header-anchor" href="#_6-控制与运动生成" aria-label="Permalink to “6 控制与运动生成”">​</a></h2><blockquote><p>主线：建模（运动学/动力学）→ 反馈（PID→MPC）→ 交互（力控）→ 生成（基元）。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>正逆运动学</td><td>DH 参数、雅可比、奇异性、数值 IK</td><td>已写（kinematics）</td></tr><tr><td>级联 PID</td><td>三环结构、带宽隔离、前馈、舵机现象对照表</td><td>已写（cascade-pid）</td></tr><tr><td>DMP</td><td>动态运动基元</td><td>已写（dmp）</td></tr><tr><td>运动基元对比</td><td>ProMP、CT-GMM 与 DMP 的取舍</td><td>扩展</td></tr><tr><td>动力学建模</td><td>拉格朗日/牛顿-欧拉</td><td>核心</td></tr><tr><td>力控</td><td>阻抗/导纳、混合位置-力控制</td><td>核心</td></tr><tr><td>LQR/MPC</td><td>状态空间、QP 求解</td><td>核心</td></tr><tr><td>足式控制</td><td>WBC、VHIP</td><td>扩展</td></tr><tr><td>RL 运动控制</td><td>边界与现状</td><td>扩展</td></tr></tbody></table><h2 id="_7-软件与中间件" tabindex="-1">7 软件与中间件 <a class="header-anchor" href="#_7-软件与中间件" aria-label="Permalink to “7 软件与中间件”">​</a></h2><blockquote><p>主线：通信 → 架构 → 实时 → 工程化。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>DDS</td><td>以数据为中心、QoS 契约、RTPS 发现</td><td>已写（dds）</td></tr><tr><td>ROS 2 体系</td><td>图模型、TF 树、生命周期、组件化</td><td>已写（ros2）</td></tr><tr><td>数据回放与时间同步</td><td>时间戳语义、录包规范、调试协议</td><td>已写（time-sync-replay）</td></tr><tr><td>软件架构模式</td><td>状态归属/数据流向/故障隔离三决策</td><td>已写（architecture-patterns）</td></tr><tr><td>实时系统原理</td><td>调度、优先级反转、PREEMPT_RT</td><td>核心</td></tr><tr><td>安全软件</td><td>看门狗、安全状态机</td><td>核心</td></tr><tr><td>构建与 CI</td><td>CMake/colcon、仿真回归</td><td>扩展</td></tr></tbody></table><h2 id="_8-系统与仿真" tabindex="-1">8 系统与仿真 <a class="header-anchor" href="#_8-系统与仿真" aria-label="Permalink to “8 系统与仿真”">​</a></h2><blockquote><p>主线：仿真 → 建模 → 集成联调 → 测试方法论 → 安全。</p></blockquote><table tabindex="0"><thead><tr><th>知识点</th><th>内容</th><th>标注</th></tr></thead><tbody><tr><td>仿真器选型</td><td>Gazebo/Isaac/MuJoCo + 物理引擎接触求解原理</td><td>核心</td></tr><tr><td>URDF/SDF 建模</td><td>模型描述与惯性参数辨识</td><td>核心</td></tr><tr><td>整机联调流程</td><td>五类接口假设、检查单、分阶段集成</td><td>已写（integration）</td></tr><tr><td>测试方法论</td><td>测试金字塔、指标体系、消融、异常注入</td><td>已写（testing）</td></tr><tr><td>部署运维</td><td>远程监控、OTA</td><td>扩展</td></tr><tr><td>功能安全入门</td><td>ISO 10218 / TS 15066</td><td>扩展</td></tr></tbody></table><hr><h2 id="其他板块-规划从简" tabindex="-1">其他板块（规划从简） <a class="header-anchor" href="#其他板块-规划从简" aria-label="Permalink to “其他板块（规划从简）”">​</a></h2><ul><li><strong>语言原理</strong>：C++/Rust/Python 已写（&quot;设计动因&quot;四问框架）；候选续篇——Go 原理（并发模型）、TypeScript 原理（类型系统的渐进式）。</li><li><strong>前端/后端/工具</strong>：随做随写，暂不预设清单。</li><li><strong>LeetCode 题解</strong>：持续更新，与算法知识联动。</li></ul><h2 id="写作流程约定" tabindex="-1">写作流程约定 <a class="header-anchor" href="#写作流程约定" aria-label="Permalink to “写作流程约定”">​</a></h2><ol><li>动笔前在本页认领知识点，把状态改为&quot;进行中&quot;；</li><li>文章遵循各系列框架：机器人篇走&quot;内核 → 规则与行为 → 抽象&quot;三段式，语言篇走&quot;设计动因&quot;四问；</li><li>跨栏目引用用 <code>[[术语]]</code>，术语先登记 <code>glossary.ts</code>；</li><li>写完更新本页状态、补全 frontmatter、跑一次 <code>docs:build</code>。</li></ol>',38)]))}const p=d(o,[["render",h]]);export{u as __pageData,p as default};
